// Keep only real job rows. Error rows are free and carry the reason.
const rows = $input.all().map(i => i.json);
const jobs = rows.filter(r => r && r.type === 'job' && r.id && r.title);
const errors = rows.filter(r => r && (r.type === 'error' || r.error));

if (jobs.length === 0 && (errors.length > 0 || rows.length === 0)) {
  const reasons = [...new Set(errors.map(e => String(e.error || e.message || 'unknown').slice(0, 200)))].slice(0, 3).join(' | ');
  throw new Error('LinkedIn Jobs Scraper returned 0 jobs. ' + (reasons ? 'Reason: ' + reasons : 'The response was empty.') + ' Check your Apify token, balance and the search settings.');
}

const now = new Date().toISOString();
const fmtSalary = (j) => {
  if (j.salaryText) return j.salaryText;
  if (j.salaryMin || j.salaryMax) {
    return [j.salaryMin, j.salaryMax].filter(Boolean).join(' - ') + ' ' + (j.salaryCurrency || '') + (j.salaryPeriod ? ' / ' + j.salaryPeriod : '');
  }
  return '';
};

return jobs.map(j => ({
  json: {
    id: String(j.id),
    title: j.title || '',
    company: j.company || '',
    location: j.location || '',
    seniority: j.seniority || '',
    employmentType: j.employmentType || '',
    salary: fmtSalary(j).trim(),
    applicants: j.applicants ?? '',
    postedAt: j.postedAt || '',
    url: j.url || '',
    emails: Array.isArray(j.emails) ? j.emails.join(', ') : '',
    foundAt: now
  }
}));
